def classify_question(question: str) -> str:
    q_lower = question.lower()

    # Simplified keyword sets
    if any(kw in q_lower for kw in ['where is', 'location of', 'in', 'at', 'situated in']):
        return 'location'
    elif any(kw in q_lower for kw in ['who is', 'who was', 'what is the name of', 'person', 'figure', 'leader', 'author', 'artist']):
        return 'human being'
    elif any(kw in q_lower for kw in ['how many', 'how much', 'number of', 'quantity of', 'amount of', 'total', 'sum', 'count']):
        return 'numeric value'
    elif any(kw in q_lower for kw in ['what does', 'abbreviation of', 'acronym for', 'short for', 'abbr']):
        return 'abbreviation'
    elif any(kw in q_lower for kw in ['what is', 'what are', 'name of', 'identify', 'classify', 'category of', 'type of', 'kind of']):
        return 'entity'
    elif any(kw in q_lower for kw in ['define', 'meaning of', 'explanation of', 'describe', 'explain', 'concept of', 'idea of', 'principle of', 'theory of']):
        return 'description and abstract concept'
    else:
        # Default fallback: try to infer from context or use heuristics
        # If none match, assume it's a location (most common)
        return 'location'

# Test on first few questions
test_questions = [q for _, q in parsed_data[:5]]
classified = [classify_question(q) for q in test_questions]
list(zip(test_questions, classified))
